from __future__ import absolute_import, division, unicode_literals

from six import PY2, text_type

import io

import pytest

from . import support  # noqa

from html5lib.constants import namespaces
from html5lib import parse, parseFragment, HTMLParser
from html5lib.html5parser import ParseError


# tests that aren't autogenerated from text files
def test_assertDoctypeCloneable():
    doc = parse('<!DOCTYPE HTML>', treebuilder="dom")
    assert doc.cloneNode(True) is not None


def test_line_counter():
    # http://groups.google.com/group/html5lib-discuss/browse_frm/thread/f4f00e4a2f26d5c0
    assert parse("<pre>\nx\n&gt;\n</pre>") is not None


def test_namespace_html_elements_0_dom():
    doc = parse("<html></html>",
                treebuilder="dom",
                namespaceHTMLElements=True)
    assert doc.childNodes[0].namespaceURI == namespaces["html"]


def test_namespace_html_elements_1_dom():
    doc = parse("<html></html>",
                treebuilder="dom",
                namespaceHTMLElements=False)
    assert doc.childNodes[0].namespaceURI is None


def test_namespace_html_elements_0_etree():
    doc = parse("<html></html>",
                treebuilder="etree",
                namespaceHTMLElements=True)
    assert doc.tag == "{%s}html" % (namespaces["html"],)


def test_namespace_html_elements_1_etree():
    doc = parse("<html></html>",
                treebuilder="etree",
                namespaceHTMLElements=False)
    assert doc.tag == "html"


def test_unicode_file():
    assert parse(io.StringIO("a")) is not None


def test_debug_log():
    parser = HTMLParser(debug=True)
    parser.parse("<!doctype html><title>a</title><p>b<script>c</script>d</p>e")

    expected = [('dataState', 'InitialPhase', 'InitialPhase', 'processDoctype', {'type': 'Doctype'}),
                ('dataState', 'BeforeHtmlPhase', 'BeforeHtmlPhase', 'processStartTag', {'name': 'title', 'type': 'StartTag'}),
                ('dataState', 'BeforeHeadPhase', 'BeforeHeadPhase', 'processStartTag', {'name': 'title', 'type': 'StartTag'}),
                ('dataState', 'InHeadPhase', 'InHeadPhase', 'processStartTag', {'name': 'title', 'type': 'StartTag'}),
                ('rcdataState', 'TextPhase', 'TextPhase', 'processCharacters', {'type': 'Characters'}),
                ('dataState', 'TextPhase', 'TextPhase', 'processEndTag', {'name': 'title', 'type': 'EndTag'}),
                ('dataState', 'InHeadPhase', 'InHeadPhase', 'processStartTag', {'name': 'p', 'type': 'StartTag'}),
                ('dataState', 'AfterHeadPhase', 'AfterHeadPhase', 'processStartTag', {'name': 'p', 'type': 'StartTag'}),
                ('dataState', 'InBodyPhase', 'InBodyPhase', 'processStartTag', {'name': 'p', 'type': 'StartTag'}),
                ('dataState', 'InBodyPhase', 'InBodyPhase', 'processCharacters', {'type': 'Characters'}),
                ('dataState', 'InBodyPhase', 'InBodyPhase', 'processStartTag', {'name': 'script', 'type': 'StartTag'}),
                ('scriptDataState', 'TextPhase', 'TextPhase', 'processCharacters', {'type': 'Characters'}),
                ('dataState', 'TextPhase', 'TextPhase', 'processEndTag', {'name': 'script', 'type': 'EndTag'}),
                ('dataState', 'InBodyPhase', 'InBodyPhase', 'processCharacters', {'type': 'Characters'}),
                ('dataState', 'InBodyPhase', 'InBodyPhase', 'processEndTag', {'name': 'p', 'type': 'EndTag'}),
                ('dataState', 'InBodyPhase', 'InBodyPhase', 'processCharacters', {'type': 'Characters'})]

    if PY2:
        for i, log in enumerate(expected):
            log = [x.encode("ascii") if isinstance(x, text_type) else x for x in log]
            expected[i] = tuple(log)

    assert parser.log == expected


def test_no_duplicate_clone():
    frag = parseFragment("<b><em><foo><foob><fooc><aside></b></em>")
    assert len(frag) == 2


def test_self_closing_col():
    parser = HTMLParser()
    parser.parseFragment('<table><colgroup><col /></colgroup></table>')
    assert not parser.errors


# A page with a valid doctype but a table cell forcibly closed by an early
# </table>; the table repair emits "unexpected-cell-end-tag".
broken_table_doc = ("<!DOCTYPE html><html><body><table>"
                    "<tr><td><div>amount 100.00</table></body></html>")

# A structurally fine page that simply omits the doctype.
missing_doctype_doc = ("<html><body><table><tr><td>100.00</td></tr>"
                       "</table></body></html>")


def test_no_error_policy_keeps_legacy_behavior():
    parser = HTMLParser()
    parser.parse(broken_table_doc)
    assert [code for _, code, _ in parser.errors] == ["unexpected-cell-end-tag"]


def test_strict_blocks_every_error():
    parser = HTMLParser(strict=True)
    with pytest.raises(ParseError) as exc_info:
        parser.parse(missing_doctype_doc)
    error = exc_info.value
    assert error.errorcode == "expected-doctype-but-got-start-tag"
    assert error.position == (1, 6)


def test_table_policy_blocks_table_error_with_code_and_position():
    parser = HTMLParser(errorPolicy="table")
    with pytest.raises(ParseError) as exc_info:
        parser.parse(broken_table_doc)
    error = exc_info.value
    assert error.errorcode == "unexpected-cell-end-tag"
    assert error.position == (1, 68)
    assert str(error) == ("Got table cell end tag (td) while required end tags "
                          "are missing. (line 1, column 68)")


def test_table_policy_tolerates_missing_doctype():
    parser = HTMLParser(errorPolicy="table")
    parser.parse(missing_doctype_doc)
    assert [code for _, code, _ in parser.errors] == [
        "expected-doctype-but-got-start-tag"]


def test_doctype_policy_blocks_missing_doctype():
    parser = HTMLParser(errorPolicy="doctype")
    with pytest.raises(ParseError) as exc_info:
        parser.parse(missing_doctype_doc)
    error = exc_info.value
    assert error.errorcode == "expected-doctype-but-got-start-tag"
    assert error.position == (1, 6)


def test_doctype_policy_tolerates_broken_table():
    parser = HTMLParser(errorPolicy="doctype")
    parser.parse(broken_table_doc)
    assert [code for _, code, _ in parser.errors] == ["unexpected-cell-end-tag"]


def test_two_policies_give_different_results_for_same_page():
    blocking = HTMLParser(errorPolicy="table")
    with pytest.raises(ParseError):
        blocking.parse(broken_table_doc)

    permissive = HTMLParser(errorPolicy="doctype")
    assert permissive.parse(broken_table_doc) is not None


def test_explicit_error_code_iterable():
    parser = HTMLParser(errorPolicy=["unexpected-cell-end-tag"])
    with pytest.raises(ParseError) as exc_info:
        parser.parse(broken_table_doc)
    assert exc_info.value.errorcode == "unexpected-cell-end-tag"


def test_empty_policy_blocks_nothing_but_records_everything():
    parser = HTMLParser(errorPolicy=[])
    parser.parse(broken_table_doc)
    assert [code for _, code, _ in parser.errors] == ["unexpected-cell-end-tag"]


def test_error_recorded_before_blocking_raise():
    parser = HTMLParser(errorPolicy="table")
    with pytest.raises(ParseError):
        parser.parse(broken_table_doc)
    position, code, datavars = parser.errors[-1]
    assert code == "unexpected-cell-end-tag"
    assert position == (1, 68)
    assert datavars == {"name": "td"}


def test_unknown_error_category_raises_value_error():
    with pytest.raises(ValueError):
        HTMLParser(errorPolicy="not-a-category")


def test_strict_and_error_policy_are_mutually_exclusive():
    with pytest.raises(TypeError):
        HTMLParser(strict=True, errorPolicy="table")


def test_unknown_error_code_falls_back_to_code_in_message():
    # "unexpected-EOF-after-attribute-value" is emitted by the tokenizer but
    # missing from the constants.E message table.
    parser = HTMLParser(errorPolicy=["unexpected-EOF-after-attribute-value"])
    with pytest.raises(ParseError) as exc_info:
        parser.parse('<a href="x"')
    error = exc_info.value
    assert error.errorcode == "unexpected-EOF-after-attribute-value"
    assert error.position == (1, 11)
    assert str(error) == ("unexpected-EOF-after-attribute-value "
                          "(line 1, column 11)")
